() => {
  const issues = [];
  document.querySelectorAll('svg').forEach((svg, si) => {
    const vb = svg.viewBox.baseVal;
    svg.querySelectorAll('text').forEach(t => {
      try {
        const b = t.getBBox();
        const over = (b.x < vb.x - 2) || (b.y < vb.y - 2) || (b.x + b.width > vb.x + vb.width + 2) || (b.y + b.height > vb.y + vb.height + 2);
        if (over) issues.push({svg: si, text: t.textContent.slice(0,40), bbox: {x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height)}, viewBox: {w: vb.width, h: vb.height}});
      } catch(e) {}
    });
  });
  // also check for horizontal page overflow
  const docOver = document.documentElement.scrollWidth - document.documentElement.clientWidth;
  // check overlapping text pairs within each svg (crude): skip
  return {svgCount: document.querySelectorAll('svg').length, textOverflowIssues: issues, horizontalPageOverflowPx: docOver};
}

() => {
  window.scrollTo(0,0);
  const over = document.documentElement.scrollWidth - document.documentElement.clientWidth;
  const toc = document.querySelector('.mobile-toc');
  const tocVisible = toc && getComputedStyle(toc).display !== 'none';
  const rail = document.querySelector('.chapter-rail');
  const railHidden = rail && getComputedStyle(rail).display === 'none';
  // find widest offenders if overflow
  let offenders = [];
  if (over > 0) {
    document.querySelectorAll('pre, table, .comparison, .workflow, img, svg, .terminal').forEach(el => {
      const r = el.getBoundingClientRect();
      if (r.right > document.documentElement.clientWidth + 1) offenders.push({tag: el.tagName + '.' + (el.className.baseVal||el.className||'').toString().split(' ')[0], right: Math.round(r.right), vw: document.documentElement.clientWidth});
    });
  }
  return {horizontalOverflowPx: over, mobileTocVisible: tocVisible, railHidden, offenders: offenders.slice(0,8)};
}
